// Firebase client configuration.
//
// Android values are generated by FlutterFire and mirrored in
// android/app/google-services.json. iOS and Web values must be supplied at
// build time until those platform apps are registered in the production
// Firebase project:
//
//   --dart-define=SNAPPRINT_FIREBASE_IOS_API_KEY=...
//   --dart-define=SNAPPRINT_FIREBASE_IOS_APP_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_IOS_MESSAGING_SENDER_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_IOS_PROJECT_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_IOS_STORAGE_BUCKET=...
//
//   --dart-define=SNAPPRINT_FIREBASE_WEB_API_KEY=...
//   --dart-define=SNAPPRINT_FIREBASE_WEB_APP_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_WEB_MESSAGING_SENDER_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_WEB_PROJECT_ID=...
//   --dart-define=SNAPPRINT_FIREBASE_WEB_AUTH_DOMAIN=...
//   --dart-define=SNAPPRINT_FIREBASE_WEB_STORAGE_BUCKET=...

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static const _webApiKey = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_API_KEY',
  );
  static const _webAppId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_APP_ID',
  );
  static const _webMessagingSenderId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_MESSAGING_SENDER_ID',
  );
  static const _webProjectId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_PROJECT_ID',
  );
  static const _webAuthDomain = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_AUTH_DOMAIN',
  );
  static const _webStorageBucket = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_WEB_STORAGE_BUCKET',
  );

  static const _iosApiKey = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_IOS_API_KEY',
  );
  static const _iosAppId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_IOS_APP_ID',
  );
  static const _iosMessagingSenderId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_IOS_MESSAGING_SENDER_ID',
  );
  static const _iosProjectId = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_IOS_PROJECT_ID',
  );
  static const _iosStorageBucket = String.fromEnvironment(
    'SNAPPRINT_FIREBASE_IOS_STORAGE_BUCKET',
  );

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) return web;
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not configured for this platform.',
        );
    }
  }

  static FirebaseOptions get web => FirebaseOptions(
    apiKey: _requiredDefine('SNAPPRINT_FIREBASE_WEB_API_KEY', _webApiKey),
    appId: _requiredDefine('SNAPPRINT_FIREBASE_WEB_APP_ID', _webAppId),
    messagingSenderId: _requiredDefine(
      'SNAPPRINT_FIREBASE_WEB_MESSAGING_SENDER_ID',
      _webMessagingSenderId,
    ),
    projectId: _requiredDefine(
      'SNAPPRINT_FIREBASE_WEB_PROJECT_ID',
      _webProjectId,
    ),
    authDomain: _requiredDefine(
      'SNAPPRINT_FIREBASE_WEB_AUTH_DOMAIN',
      _webAuthDomain,
    ),
    storageBucket: _requiredDefine(
      'SNAPPRINT_FIREBASE_WEB_STORAGE_BUCKET',
      _webStorageBucket,
    ),
  );

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyBmhzn9u3G2ZyZFoarAUtsx51-S1yVjsKk',
    appId: '1:204019052123:android:1bbdae20c59b5b1b20197e',
    messagingSenderId: '204019052123',
    projectId: 'snapprint-5076c',
    storageBucket: 'snapprint-5076c.firebasestorage.app',
  );

  static FirebaseOptions get ios => FirebaseOptions(
    apiKey: _requiredDefine('SNAPPRINT_FIREBASE_IOS_API_KEY', _iosApiKey),
    appId: _requiredDefine('SNAPPRINT_FIREBASE_IOS_APP_ID', _iosAppId),
    messagingSenderId: _requiredDefine(
      'SNAPPRINT_FIREBASE_IOS_MESSAGING_SENDER_ID',
      _iosMessagingSenderId,
    ),
    projectId: _requiredDefine(
      'SNAPPRINT_FIREBASE_IOS_PROJECT_ID',
      _iosProjectId,
    ),
    storageBucket: _requiredDefine(
      'SNAPPRINT_FIREBASE_IOS_STORAGE_BUCKET',
      _iosStorageBucket,
    ),
    iosBundleId: 'com.snapprint.app',
  );

  static String _requiredDefine(String name, String value) {
    if (value.isEmpty) {
      throw StateError(
        '$name must be supplied with --dart-define for this platform.',
      );
    }
    return value;
  }
}
